        [global::System.Configuration.UserScopedSettingAttribute()]
        [global::System.Diagnostics.DebuggerNonUserCodeAttribute()]
        [global::System.Configuration.DefaultSettingValueAttribute("SELECT VMID\r\n     , NAME\r\n     , MEM_SIZE_MB\r\n     , NUM_VCPU\r\n     , POWER_STATE" +
            "\r\n     , ISNULL(CASE [Guest_OS] \r\n         WHEN \'centosGuest\' THEN \'CENTOS\' \r\n  " +
            "       WHEN \'other26xLinux64Guest\' THEN \'Linux 2.6 Kernel x64\' \r\n         WHEN \'" +
            "other26xLinuxGuest\' THEN \'Linux 2.6 Kernel x86\' \r\n         WHEN \'otherGuest\' THE" +
            "N \'Unknown\'\r\n         WHEN \'redhatGuest\' THEN \'Red Hat x86\' \r\n         WHEN \'rhe" +
            "l4_64Guest\' THEN \'Red Hat Enterprise Linux 4 x64\' \r\n         WHEN \'rhel5Guest\' T" +
            "HEN \'Red Hat Enterprise Linux 5 x86\' \r\n         WHEN \'sles11_64Guest\' THEN \'SUSE" +
            " Linux Enterprise Server 11 x64\'\r\n         WHEN \'win2000ServGuest\' THEN \'Windows" +
            " Server 2000 Standard x86\' \r\n         WHEN \'windows7Guest\' THEN \'Windows 7 x86\' " +
            "\r\n         WHEN \'windows7_64Guest\' THEN \'Windows 7 x64\' \r\n         WHEN \'windows" +
            "8Server64Guest\' THEN \'Windows Server 2012 x64\' \r\n         WHEN \'windows7Server64" +
            "Guest\' THEN \'Windows Server 2008 R2 x64\' \r\n         WHEN \'winLonghorn64Guest\' TH" +
            "EN \'Windows Server 2008 x64\' \r\n         WHEN \'winLonghornGuest\' THEN \'Windows Se" +
            "rver 2008 x86\'\r\n         WHEN \'winNetEnterpriseGuest\' THEN \'Windows Server 2003 " +
            "Enterprise x86\' \r\n         WHEN \'winNetStandard64Guest\' THEN \'Windows Server 200" +
            "3 Standard x64\' \r\n         WHEN \'winNetStandardGuest\' THEN \'Windows Server 2003 " +
            "Standard x86\'\r\n         WHEN \'winVistaGuest\' THEN \'Windows Vista x86\' \r\n        " +
            " WHEN \'winXPProGuest\' THEN \'Windows XP Professional x86\' \r\n         WHEN \'winNet" +
            "Enterprise64Guest\' THEN \'Windows Server 2003 Enterprise x64\' \r\n         WHEN \'or" +
            "acleLinux64Guest\' THEN \'Oracle Linux x64\' \r\n         WHEN \'freebsd64Guest\' THEN " +
            "\'FreeBSD x64\' \r\n         WHEN \'ubuntu64Guest\' THEN \'Ubuntu x64\' \r\n         WHEN " +
            "\'solaris10Guest\' THEN \'Solaris 10 x86\' \r\n         WHEN \'solaris10_64Guest\' THEN " +
            "\'Solaris 10 x64\'\r\n         WHEN \'otherLinux64Guest\' THEN \'Linux x64\' \r\n         " +
            "ELSE Guest_OS \r\n       END,\'\') AS GuestOS\r\n     , ISNULL(GUEST_FAMILY,\'\')\r\n     " +
            ", MEMORY_OVERHEAD / (1024 * 1024) AS Mem_Ovhd\r\n     , ISNULL(REPLACE(UPPER(DNS_N" +
            "AME), \'.CORP.EXAMPLE.ORG\', \'\'),\'\') AS DNS_NAME\r\n     , ISNULL(IP_ADDRESS,\'\')\r\n     " +
            ", VMMWARE_TOOL\r\n     , NUM_NIC\r\n     , NUM_DISK\r\n     , CASE [IS_TEMPLATE] \r\n   " +
            "      WHEN 1 THEN \'True\' \r\n         WHEN 0 THEN \'False\' \r\n       END AS Template" +
            "\r\n     , DESCRIPTION\r\n     , ANNOTATION\r\n     , CONVERT(DECIMAL(10, 0), ROUND(AG" +
            "GR_COMMITED_STORAGE_SPACE / (1024 * 1024), 0)) AS Agg_CommDiskMB\r\n     , CONVERT" +
            "(DECIMAL(10, 0), ROUND(AGGR_UNCOMMITED_STORAGE_SPACE / (1024 * 1024), 0)) AS Agg" +
            "_UnCommDiskMB\r\n     , CONVERT(DECIMAL(10, 0), ROUND(AGGR_UNSHARED_STORAGE_SPACE " +
            "/ (1024 * 1024), 0)) AS Agg_UnSharDiskMB\r\nFROM VPXV_VMS WITH (NOLOCK, NOWAIT)\r\nO" +
            "RDER BY NAME")]
        public string vCenter_InformationQuery {
            get {
                return ((string)(this["vCenter_InformationQuery"]));
