        [global::System.Configuration.UserScopedSettingAttribute()]
        [global::System.Diagnostics.DebuggerNonUserCodeAttribute()]
        [global::System.Configuration.DefaultSettingValueAttribute("SELECT Drawing.ObjectID                 AS DrawingID\r\n     , Drawing.CurrentVersi" +
            "onID         AS DrawingVersionID\r\n     , Drawing.ObjectName               AS Dra" +
            "wingName\r\n     , Drawing.ObjectDescription        AS DrawingDescription\r\n     , " +
            "Version.SystemVersionNo          AS DrawingVersion\r\n     , PagePreviews.PagePrev" +
            "iewImage    AS DrawingImage\r\n     , CASE ISNULL(DrawingStatus.ValueText, -1)\r\n  " +
            "        WHEN -1 THEN \'N/A\'\r\n          WHEN 0  THEN \'Draft\'\r\n          WHEN 1  TH" +
            "EN \'Pending Review\'\r\n          WHEN 2  THEN \'Approved\'\r\n          ELSE DrawingSt" +
            "atus.ValueText\r\n        END                             AS DrawingStatus\r\n     ," +
            " DrawingFocusedService.ValueText  AS DrawingFocusedServiceName\r\n     , LastDrawi" +
            "ngUpdate.AttributeValue AS LastUpdate\r\n     , Version.Notes\r\nFROM Object Drawing" +
            "\r\nINNER JOIN vwObject v ON Drawing.ObjectID = v.ObjectID\r\nINNER JOIN (SELECT v.O" +
            "bjectID\r\n                 , MAX(v.SystemVersionNo) AS SystemVersionNo\r\n         " +
            "        , o.CurrentVersionId AS ID\r\n            FROM Object AS o \r\n            I" +
            "NNER JOIN Version AS v ON o.ObjectID = v.ObjectID\r\n            GROUP BY v.Object" +
            "ID, o.CurrentVersionId \r\n           ) AS Version                         ON v.Cu" +
            "rrentVersionId                = Version.ID\r\nINNER JOIN VisioPagePreviews PagePre" +
            "views       ON PagePreviews.ObjectID             = Version.ObjectId   AND PagePr" +
            "eviews.VersionId            = Version.ID\r\nINNER JOIN AttributeValue DrawingStatu" +
            "s         ON DrawingStatus.AttributeId         = \'#DRAWINGSTATUS#\'  AND DrawingS" +
            "tatus.VersionId           = Version.ID\r\nINNER JOIN AttributeValue LastDrawingUpd" +
            "ate     ON LastDrawingUpdate.AttributeId     = \'#LASTUPDATE#\'     AND LastDrawin" +
            "gUpdate.VersionId           = Drawing.ObjectVersionId\r\nINNER JOIN AttributeValue" +
            " DrawingFocusedService ON DrawingFocusedService.AttributeId = \'#FOCUSEDSERVICE#\'" +
            " AND DrawingFocusedService.VersionId   = Version.ID\r\nWHERE v.TypeId           = " +
            "#DRAWINGID# AND \r\n      Drawing.DeleteFlag = 0   AND \r\n      v.ObjectParentID   " +
            "= \'#DOCUMENTROOTID#\'\r\nORDER BY Drawing.ObjectName")]
        public string iServer33400_GetDrawingsQuery {
            get {
                return ((string)(this["iServer33400_GetDrawingsQuery"]));
            }
            set {
                this["iServer33400_GetDrawingsQuery"] = value;
            }
        }
        
        [global::System.Configuration.UserScopedSettingAttribute()]
