        [global::System.Configuration.DefaultSettingValueAttribute("SELECT ObjectID\r\n     , ObjectName\r\n     , ObjectDescription\r\n     , CurrentVersi" +
            "onId\r\nFROM vwObject v \r\nWHERE v.ObjectName LIKE \'#FOCUSEDSERVICENAME#\' \r\n  AND v" +
            ".TypeId = #BusinessApplicationID#")]
