        [global::System.Configuration.UserScopedSettingAttribute()]
        [global::System.Diagnostics.DebuggerNonUserCodeAttribute()]
        [global::System.Configuration.DefaultSettingValueAttribute("SELECT DISTINCT Service.ObjectID             AS ServiceID\r\n     , ObjectName     " +
            "                       AS ServiceName\r\n     , ObjectDescription                 " +
            "    AS ServiceDescription\r\n     , CurrentVersionId                      AS Servi" +
            "ceVersionID\r\n     , Service.SystemVersionNo               AS ServiceVersion\r\n   " +
            "  , Tier.ValueBigInt                      AS Tier\r\n     --, ShowInRunbook.ValueB" +
            "igInt             AS ShowInRunbook\r\n     , RunbookOrder.ValueBigInt             " +
            " AS RunbookOrder\r\n     , ServiceDisplayName.ValueText          AS ServiceDisplay" +
            "Name\r\n     , ShowInServiceCatalogue.ValueBigInt    AS ShowInServiceCatalogue\r\n  " +
            "   , SubService.ValueBigInt                AS SubService\r\n     , InScope.ValueBi" +
            "gInt                   AS InScope\r\nFROM vwObject Service\r\nINNER JOIN (SELECT v.O" +
            "bjectID\r\n                 , MAX(v.SystemVersionNo) AS SystemVersionNo\r\n         " +
            "        , o.CurrentVersionId AS ID\r\n            FROM Object AS o \r\n            I" +
            "NNER JOIN Version AS v ON o.ObjectID = v.ObjectID\r\n            GROUP BY v.Object" +
            "ID, o.CurrentVersionId \r\n           ) AS Version                         ON Serv" +
            "ice.CurrentVersionId =         Version.ID  \r\nLEFT JOIN AttributeValue Stream    " +
            "             ON Stream.VersionId =                 Service.CurrentVersionId AND " +
            "Stream.AttributeId =                 \'#STREAM#\'\r\nLEFT JOIN AttributeValue Tier  " +
            "                 ON Tier.VersionId =                   Service.CurrentVersionId " +
            "AND Tier.AttributeId =                   \'#TIER#\'\r\n--LEFT JOIN AttributeValue Sh" +
            "owInRunbook          ON ShowInRunbook.VersionId =          Service.CurrentVersio" +
            "nId AND ShowInRunbook.AttributeId =          \'#SHOWINRUNBOOK#\'\r\nLEFT JOIN Attrib" +
            "uteValue RunbookOrder           ON RunbookOrder.VersionId =           Service.Cu" +
            "rrentVersionId AND RunbookOrder.AttributeId =           \'#RUNBOOKORDER#\'\r\nLEFT J" +
            "OIN AttributeValue ServiceDisplayName     ON ServiceDisplayName.VersionId =     " +
            "Service.CurrentVersionId AND ServiceDisplayName.AttributeId =     \'#SERVICEDISPL" +
            "AYNAME#\'\r\nLEFT JOIN AttributeValue ShowInServiceCatalogue ON ShowInServiceCatalo" +
            "gue.VersionId = Service.CurrentVersionId AND ShowInServiceCatalogue.AttributeId " +
            "= \'#SHOWINSERVICECATALOG#\'\r\nLEFT JOIN AttributeValue SubService             ON S" +
            "ubService.VersionId =             Service.CurrentVersionId AND SubService.Attrib" +
            "uteId =             \'#SUBSERVICE#\'\r\nLEFT JOIN AttributeValue InScope            " +
            "    ON InScope.VersionId =                Service.CurrentVersionId AND InScope.A" +
            "ttributeId =                \'#INSCOPE#\'\r\nWHERE (Service.LibraryId = \'00000000-00" +
            "00-0000-0000-000000000000\') \r\n  AND (Service.IsDeleted = 0) \r\n  AND (Service.Typ" +
            "eId    = #BusinessApplicationID#) \r\n  AND (Service.ObjectID  = \'#SERVICEID#\')")]
        public string iServer33400_GetBusinessApplicationDetailsQuery {
